    reg CLK = 0, RESET = 1;
    always #5 CLK = ~CLK;
    reg [31:0] Instr_F, ReadData_M;
    wire MemRead;
    wire [3:0] MemWrite_out;
    wire [31:0] PC, ALUResult, WriteData_out;
    RV #(
        .PC_INIT(BASE)
    ) dut (
        CLK,
        RESET,
        Instr_F,
        ReadData_M,
        MemRead,
        MemWrite_out,
        PC,
        ALUResult,
        WriteData_out
    );
    reg [31:0] imem[0:WORDS-1];
