    integer seen[0:NTEST-1];
    integer i, idx, lane, cycles = 0, passed = 0, errors = 0, writes = 0;
    // Combinational reads, as in Wrapper. Data additionally requires MemRead
    // to expose wrong-stage read enables (important for memory-mapped I/O).
    always @(*) begin
        Instr_F = NOP;
        if (PC >= BASE && PC < BASE + 4 * WORDS && PC[1:0] == 0) Instr_F = imem[(PC-BASE)>>2];
        ReadData_M = 0;
        if (MemRead && ALUResult < 8192 && ALUResult[1:0] == 0) ReadData_M = dmem[ALUResult>>2];
    end
    initial begin
