                                 expected[idx], WriteData_out);
                        errors = errors + 1;
                    end
                    else begin
                        passed = passed + 1;
                        $display("PASS [%0d] %s = %h", idx, test_name[idx], WriteData_out);
                    end
                end
                else if (!(ALUResult == 32'h7fc || ALUResult == 32'h800 || ALUResult == 32'h804))
                    $fatal(1, "Unexpected store outside scratch/signature memory: %h", ALUResult);
                for (lane = 0; lane < 4; lane = lane + 1)
                if (MemWrite_out[lane]) dmem[ALUResult>>2][8*lane+:8] <= WriteData_out[8*lane+:8];
            end
            if (cycles > 200000) $fatal(1, "TIMEOUT: %0d/%0d checks", passed, NTEST);
        end
    end
endmodule
